 "content": "def transform(grid):
    """Complete a missing horizontally mirrored motif in the matching cell pair."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Separator rows/columns are uniform in the grid's framing color.
    sep_color = None
    for color in range(1, 10):
        if any(all(v == color for v in row) for row in g):
            sep_color = color
            break
    if sep_color is None:
        return g
    sep_rows = [r for r, row in enumerate(g) if all(v == sep_color for v in row)]
    sep_cols = [c for c in range(w) if all(g[r][c] == sep_color for r in range(h))]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_ranges = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_ranges = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # Each compartment maps each non-frame color to its local coordinates.
    cells = {}
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            by_color = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = g[r][c]
                    if v not in (0, sep_color):
                        by_color.setdefault(v, set()).add((r - r0, c - c0))
            cells[(ri, ci)] = by_color

    # Find the column pair evidenced by an already-present mirrored pair of
    # same-color motifs, then use it to fill a missing partner in another band.
    evidence = {}
    for color in range(1, 10):
        pairs = set()
        for ri in range(len(row_ranges)):
            for ci in range(len(col_ranges) - 1):
                left = cells[(ri, ci)].get(color)
                right = cells[(ri, ci + 1)].get(color)
                if left and right:
                    width = col_ranges[ci][1] - col_ranges[ci][0]
                    right_width = col_ranges[ci + 1][1] - col_ranges[ci + 1][0]
                    if width == right_width and {(r, width - 1 - c) for r, c in left} == right:
                        pairs.add(ci)
        if pairs:
            evidence[color] = pairs

    for color, pairs in evidence.items():
        for ci in pairs:
            for ri in range(len(row_ranges)):
                left = cells[(ri, ci)].get(color)
                right = cells[(ri, ci + 1)].get(color)
                if bool(left) == bool(right):
                    continue
                r0, r1 = row_ranges[ri]
                c0, c1 = col_ranges[ci]
                d0, d1 = col_ranges[ci + 1]
                if left:
                    for r, c in left:
                        g[r0 + r][d0 + (d1 - d0 - 1 - c)] = color
                else:
                    for r, c in right:
                        g[r0 + r][c0 + (c1 - c0 - 1 - c)] = color
    return g
